/**
 * Skill-tool extraction: one `elementum_agentic_skill_*_tool` block → the
 * normalized shape the skill printer consumes. The owning skill's from-tf
 * drives the pass and says who the owner is — this module never names the
 * skill or app resource types. Mirrors `entities/agent-tool/from-tf.ts`.
 */
import { EntityTfError } from "../../engine/entity.js";
import { dataRefLabel, optionalString, resourceRefLabel } from "../../engine/pull/context.js";
import { isTfExpr, scopedLabelToBagKey } from "../../engine/tf/index.js";
import { dataAspectDisplayName, dataAspectRefName } from "../shared/aspect-target-from-tf.js";
import { resolveToolFieldKey } from "../shared/tool-field-ref.js";
import { KNOWN_SKILL_TOOL_ATTRS, SKILL_TOOL_SUB_TYPE_BY_RESOURCE, UNAUTHORABLE_SKILL_TOOL_ATTRS, } from "./types.js";
/**
 * One tool block → its normalized shape; undefined = skipped with a
 * diagnostic (unimplemented sub-type, wrong owner, unresolvable target).
 */
export function skillToolFromTf(block, owner, ctx) {
    const subType = SKILL_TOOL_SUB_TYPE_BY_RESOURCE.get(block.type ?? "");
    if (subType === undefined) {
        ctx.diagnostics.push(`resource "${block.type}" is not a known skill tool resource; skipped`);
        return undefined;
    }
    const label = block.label;
    if (label === undefined || label === "") {
        throw new EntityTfError(`${block.type} block is missing its label`);
    }
    const attrs = block.attrs;
    const name = optionalString(attrs, "name", `tool "${label}"`, ctx) ?? "";
    const where = `skill tool "${name}" (${block.type}.${label})`;
    if (subType.implemented !== true) {
        ctx.diagnostics.push(`${where}: tool kind is not supported on the terraform path yet; skipped`);
        return undefined;
    }
    const known = KNOWN_SKILL_TOOL_ATTRS[subType.typeKey];
    for (const key of Object.keys(attrs)) {
        if (UNAUTHORABLE_SKILL_TOOL_ATTRS.has(key)) {
            ctx.diagnostics.push(`${where}: ${key} has no authoring slot on the terraform path yet; a rebuilt stream will omit it`);
        }
        else if (!known.has(key)) {
            ctx.diagnostics.push(`${where}: unhandled attribute "${key}" — the export dialect grew; extend skillToolFromTf deliberately`);
        }
    }
    if (resourceRefLabel(attrs["skill_id"], owner.skillType) !== owner.skillLabel) {
        ctx.diagnostics.push(`${where}: skill_id does not reference ${owner.skillType}.${owner.skillLabel}; skipped`);
        return undefined;
    }
    const startMessage = optionalString(attrs, "start_message", where, ctx);
    const status = optionalString(attrs, "status", where, ctx);
    let runAs;
    const runAsValue = optionalString(attrs, "run_as", where, ctx);
    if (runAsValue === "current_user")
        runAs = { currentUser: true };
    else if (runAsValue === "publisher")
        runAs = { publisher: true };
    else if (runAsValue === "service_account") {
        const serviceAccountLabel = dataRefLabel(attrs["service_account_id"], "elementum_service_account");
        if (serviceAccountLabel !== undefined) {
            const serviceAccountName = ctx.dataName("elementum_service_account", serviceAccountLabel);
            if (serviceAccountName !== undefined && serviceAccountName !== "") {
                runAs = {
                    serviceAccount: {
                        __kind: "serviceAccount",
                        appRefName: owner.appLabel,
                        name: serviceAccountName,
                    },
                };
            }
            else {
                ctx.diagnostics.push(`${where}: service_account_id references data.elementum_service_account.${serviceAccountLabel}, but the stream has no matching named data block; dropped`);
            }
        }
        else {
            const resourceLabel = resourceRefLabel(attrs["service_account_id"], "elementum_service_account");
            const imported = typeof attrs["service_account_id"] === "string"
                ? ctx.importedResource?.(attrs["service_account_id"])
                : undefined;
            const account = resourceLabel !== undefined
                ? ctx.resourceByAddress?.(`elementum_service_account.${resourceLabel}`)
                : imported?.type === "elementum_service_account" ? imported : undefined;
            const explicitName = account?.attrs["name"];
            const firstName = account?.attrs["first_name"];
            const lastName = account?.attrs["last_name"];
            const serviceAccountName = typeof explicitName === "string" && explicitName !== ""
                ? explicitName
                : typeof firstName === "string" && typeof lastName === "string" ? `${firstName} ${lastName}` : undefined;
            if (serviceAccountName !== undefined) {
                runAs = {
                    serviceAccount: {
                        __kind: "serviceAccount",
                        appRefName: owner.appLabel,
                        name: serviceAccountName,
                    },
                };
            }
            else {
                ctx.diagnostics.push(`${where}: service_account_id is not a named data.elementum_service_account reference; use a serviceAccountRef({ app, name }); dropped`);
            }
        }
    }
    else if (runAsValue !== undefined) {
        ctx.diagnostics.push(`${where}: unsupported run_as ${JSON.stringify(runAsValue)}; dropped`);
    }
    const common = {
        name,
        description: optionalString(attrs, "description", where, ctx) ?? "",
        ...(status === "INACTIVE" && { status: "INACTIVE" }),
        ...(startMessage !== undefined && { startMessage }),
        ...(runAs !== undefined && { runAs }),
    };
    if (subType.typeKey === "runAgent") {
        const targetLabel = resourceRefLabel(attrs["target_agent_id"], "elementum_agent");
        if (targetLabel === undefined) {
            ctx.diagnostics.push(`${where}: target_agent_id is not an elementum_agent resource reference; skipped`);
            return undefined;
        }
        return {
            typeKey: "runAgent",
            ...common,
            targetAgentKey: scopedLabelToBagKey(owner.ownerTfLabel, targetLabel),
            workerTaskPrompt: optionalString(attrs, "worker_task_prompt", where, ctx) ?? "",
        };
    }
    if (subType.typeKey === "automation") {
        const automation = attrs["automation_id"];
        const automationLabel = isTfExpr(automation) &&
            automation.$expr === "resource-attr" &&
            (automation.type === "elementum_workflow_publish" || automation.type === "elementum_automation")
            ? automation.label
            : undefined;
        const automationRawId = typeof automation === "string" && automation !== "" ? automation : undefined;
        if (automationLabel === undefined && automationRawId === undefined) {
            ctx.diagnostics.push(`${where}: automation_id is not an automation/workflow_publish resource reference; skipped`);
            return undefined;
        }
        const inputs = [];
        for (const item of Array.isArray(attrs["inputs"]) ? attrs["inputs"] : []) {
            if (typeof item !== "object" || item === null || Array.isArray(item) || isTfExpr(item))
                continue;
            const rec = item;
            if (typeof rec["parameter_name"] !== "string" || rec["parameter_name"] === "") {
                ctx.diagnostics.push(`${where}: inputs item has no parameter_name; dropped`);
                continue;
            }
            inputs.push({
                parameterName: rec["parameter_name"],
                ...(typeof rec["display_name"] === "string" && { displayName: rec["display_name"] }),
                ...(typeof rec["description"] === "string" && { description: rec["description"] }),
                ...(typeof rec["required"] === "boolean" && { required: rec["required"] }),
            });
        }
        // The tool's own `inputs` attribute can be genuinely absent even when the
        // target automation's onDemand trigger declares required parameters —
        // the platform doesn't enforce that binding at tool-creation time (a
        // live Deloitte "sentiment-analysis" skill hit this: a `run_automation`
        // tool with zero `inputs` targeting an automation whose trigger requires
        // one). `AutomationToolV2` (entities/agent/tools.ts) requires every such
        // parameter to be mapped, so printing nothing here would emit a
        // `skillAutomation({...})` call that can't compile (edk#483). This must
        // NOT be "fixed" by inventing an `inputs` entry that isn't really on the
        // platform — `elementum build` re-serializes whatever `inputs` prints
        // straight back to HCL, so a fabricated entry becomes a genuine plan
        // diff proposing to write fake data onto a live tool (caught live: a
        // rebuilt `run_automation` tool proposed adding an `inputs` block with a
        // literal "TODO: ..." description). Only RECORD which required
        // parameters are unmapped; `printTool` (print-skill-v2.ts) decides how
        // to keep the generated file compiling without asserting any of this as
        // real authored data.
        const mappedParams = new Set(inputs.map((i) => i.parameterName));
        // Found by following the trigger's OWN `automation` reference (mirrors
        // `automationFromTfDocument`'s `references(block.attrs.automation, ...)`
        // in entities/automation/from-tf.ts) rather than guessing that the
        // trigger shares its automation's Terraform label — that label equality
        // holds by observed export convention, not by contract, and a silent
        // miss here would reproduce the exact tsc-failing call this fix is for,
        // with no diagnostic to explain why.
        const trigger = automationLabel === undefined
            ? undefined
            : ctx.resourcesOfType?.("elementum_on_demand_trigger").find((block) => {
                const ref = block.attrs["automation"];
                return isTfExpr(ref) && ref.$expr === "resource-attr" && ref.type === "elementum_automation" && ref.label === automationLabel;
            });
        const missingRequiredInputs = [];
        for (const item of Array.isArray(trigger?.attrs["parameters"]) ? trigger.attrs["parameters"] : []) {
            if (typeof item !== "object" || item === null || Array.isArray(item) || isTfExpr(item))
                continue;
            const rec = item;
            if (rec["required"] !== true || typeof rec["name"] !== "string" || mappedParams.has(rec["name"]))
                continue;
            ctx.diagnostics.push(`${where}: target automation's onDemand trigger requires "${rec["name"]}", but this tool has no input mapping for it — printed source will need a human-authored inputs entry before this tool can be adopted`);
            missingRequiredInputs.push(rec["name"]);
        }
        const outputs = [];
        for (const item of Array.isArray(attrs["outputs"]) ? attrs["outputs"] : []) {
            if (typeof item !== "object" || item === null || Array.isArray(item) || isTfExpr(item))
                continue;
            const rec = item;
            if (typeof rec["workflow_property_name"] !== "string" || rec["workflow_property_name"] === "") {
                ctx.diagnostics.push(`${where}: outputs item has no workflow_property_name; dropped`);
                continue;
            }
            outputs.push({
                workflowPropertyName: rec["workflow_property_name"],
                ...(typeof rec["display_name"] === "string" && { displayName: rec["display_name"] }),
                ...(typeof rec["description"] === "string" && { description: rec["description"] }),
            });
        }
        return {
            typeKey: "automation",
            ...common,
            ...(automationRawId !== undefined
                ? { automationRawId }
                : { automationKey: scopedLabelToBagKey(owner.ownerTfLabel, automationLabel) }),
            ...(inputs.length > 0 && { inputs }),
            ...(outputs.length > 0 && { outputs }),
            ...(missingRequiredInputs.length > 0 && { missingRequiredInputs }),
        };
    }
    let searchTableKey;
    let searchTableName;
    if (subType.typeKey === "searchTable") {
        const value = attrs["search_table_id"];
        const resourceTypes = ["elementum_ai_search_table", "elementum_linked_ai_search_table", "elementum_table_search_table"];
        const matched = resourceTypes
            .map((type) => ({ type, label: resourceRefLabel(value, type) }))
            .find((candidate) => candidate.label !== undefined);
        if (matched?.label !== undefined) {
            // A managed or linked search table is owned by an ELEMENT, so its label
            // carries the `elements_<ns>_` prefix — decoding it with app scope leaves
            // the prefix in place and camel-cases the whole label into a bag key that
            // matches nothing. The table variant keeps its existing app-scope
            // handling: a table-owned search table reached through a tool is not
            // modelled end to end yet.
            const scope = matched.type === "elementum_table_search_table" ? "app" : "element";
            searchTableKey = scopedLabelToBagKey(owner.ownerTfLabel, matched.label, scope);
        }
        else if (isTfExpr(value) && value.$expr === "data-attr" && value.type === "elementum_search_table") {
            searchTableName = ctx.dataName(value.type, value.label);
            if (searchTableName === undefined) {
                ctx.diagnostics.push(`${where}: search_table_id references data.${value.type}.${value.label} without a matching name lookup; skipped`);
                return undefined;
            }
        }
        else {
            ctx.diagnostics.push(`${where}: search_table_id is not a supported search-table resource reference; skipped`);
            return undefined;
        }
    }
    // Target: the owning app's resource ref = self; a data.elementum_app ref =
    // a foreign app, resolved to its display name via the stream's data block.
    const targetAttr = attrs["target_id"];
    let target;
    // The tool's fields are scoped under the RESOLVED target aspect, not
    // always the owning app (board issue #169) — a field on a foreign
    // app/element carries that aspect's own label, mirroring the
    // foreignApp/foreignElement resolution below.
    let fieldScopeLabel = owner.ownerTfLabel;
    let fieldScope = "app";
    const selfLabel = resourceRefLabel(targetAttr, owner.appType);
    if (selfLabel === owner.appLabel) {
        target = { kind: "self" };
    }
    else if (isTfExpr(targetAttr) && targetAttr.$expr === "data-attr" && targetAttr.type === "elementum_app") {
        const appName = dataAspectDisplayName(ctx, "app", targetAttr.label);
        if (appName === undefined) {
            ctx.diagnostics.push(`${where}: target_id references data.elementum_app.${targetAttr.label} but the stream has no such data block; skipped`);
            return undefined;
        }
        const attrs = ctx.dataAttrs?.("elementum_app", targetAttr.label);
        const namespace = typeof attrs?.namespace === "string" ? attrs.namespace : undefined;
        const refName = dataAspectRefName(ctx, "app", targetAttr.label, appName);
        target = {
            kind: "foreignApp",
            name: appName,
            ...(refName !== undefined && { refName }),
            ...(namespace !== undefined && { namespace }),
        };
        fieldScopeLabel = targetAttr.label;
    }
    else if (isTfExpr(targetAttr) && targetAttr.$expr === "data-attr" && targetAttr.type === "elementum_element") {
        // Board issue #42: an aspect target can be an element, not just an app.
        const elementName = dataAspectDisplayName(ctx, "element", targetAttr.label);
        if (elementName === undefined) {
            ctx.diagnostics.push(`${where}: target_id references data.elementum_element.${targetAttr.label} but the stream has no such data block; skipped`);
            return undefined;
        }
        const attrs = ctx.dataAttrs?.("elementum_element", targetAttr.label);
        const namespace = typeof attrs?.namespace === "string" ? attrs.namespace : undefined;
        const refName = dataAspectRefName(ctx, "element", targetAttr.label, elementName);
        target = {
            kind: "foreignElement",
            name: elementName,
            ...(refName !== undefined && { refName }),
            ...(namespace !== undefined && { namespace }),
        };
        fieldScopeLabel = targetAttr.label;
        fieldScope = "element";
    }
    else if (typeof targetAttr === "string") {
        // No portable reference was available at export time (ei fell back to
        // the raw platform UUID) — keep the tool with an unresolved target
        // instead of dropping it entirely (board issue #648).
        ctx.diagnostics.push(`${where}: target_id could not be resolved to a portable reference ("${targetAttr}"); kept as unresolved`);
        target = { kind: "unresolved", uuid: targetAttr };
    }
    else {
        ctx.diagnostics.push(`${where}: target_id has an unrecognized shape (${JSON.stringify(targetAttr)}); skipped`);
        return undefined;
    }
    let fields;
    const rawFields = attrs["fields"];
    if (Array.isArray(rawFields)) {
        fields = [];
        for (const item of rawFields) {
            if (typeof item !== "object" || item === null || Array.isArray(item) || isTfExpr(item)) {
                ctx.diagnostics.push(`${where}: fields item has an unrecognized shape; dropped`);
                continue;
            }
            const rec = item;
            const fieldKey = resolveToolFieldKey(rec["field_id"], fieldScopeLabel, fieldScope, ctx);
            // A field on a foreign/out-of-scope aspect has no field resource ei
            // can reference — it falls back to a bare platform id, confirmed live
            // (board issue #169). Preserve it (raw-id TODO placeholder) rather
            // than silently dropping the field.
            const rawFieldId = fieldKey === undefined && typeof rec["field_id"] === "string" && rec["field_id"] !== "" ? rec["field_id"] : undefined;
            if (fieldKey === undefined && rawFieldId === undefined) {
                ctx.diagnostics.push(`${where}: fields item's field_id is not a field resource reference; dropped`);
                continue;
            }
            fields.push({
                ...(fieldKey !== undefined ? { key: fieldKey } : { rawFieldId: rawFieldId }),
                ...(typeof rec["name"] === "string" && { name: rec["name"] }),
                ...(typeof rec["description"] === "string" && { description: rec["description"] }),
                // The provider's own schema docs `required` on search-tool fields as
                // "Not used by search tools" — it's platform-generated noise (see
                // to-tf.ts), so it's excluded here too rather than echoed into
                // authored source.
                ...((subType.typeKey === "createRecord" || subType.typeKey === "updateRecord") &&
                    typeof rec["required"] === "boolean" && { required: rec["required"] }),
                ...((subType.typeKey === "createRecord" || subType.typeKey === "updateRecord") &&
                    typeof rec["default_value"] === "string" && { defaultValue: rec["default_value"] }),
            });
        }
        if (fields.length === 0)
            fields = undefined;
    }
    else if (rawFields !== undefined) {
        ctx.diagnostics.push(`${where}: fields is not a list; dropped`);
    }
    if ((subType.typeKey === "searchAspect" || subType.typeKey === "searchTable") && attrs["filter"] !== undefined) {
        ctx.diagnostics.push(`${where}: filter is not supported on the terraform path yet; a rebuilt stream will omit it`);
    }
    let filterVariables;
    const rawFilterVariables = attrs["filter_variables"];
    if ((subType.typeKey === "searchAspect" || subType.typeKey === "searchTable") && Array.isArray(rawFilterVariables)) {
        filterVariables = [];
        for (const item of rawFilterVariables) {
            if (typeof item !== "object" || item === null || Array.isArray(item) || isTfExpr(item)) {
                ctx.diagnostics.push(`${where}: filter_variables item has an unrecognized shape; dropped`);
                continue;
            }
            const rec = item;
            if (typeof rec["id"] !== "string" || rec["id"] === "" || typeof rec["name"] !== "string" || typeof rec["description"] !== "string" || typeof rec["required"] !== "boolean") {
                ctx.diagnostics.push(`${where}: filter_variables item is missing a required attribute; dropped`);
                continue;
            }
            filterVariables.push({ id: rec["id"], name: rec["name"], description: rec["description"], required: rec["required"] });
        }
        if (filterVariables.length === 0)
            filterVariables = undefined;
    }
    else if ((subType.typeKey === "searchAspect" || subType.typeKey === "searchTable") && rawFilterVariables !== undefined) {
        ctx.diagnostics.push(`${where}: filter_variables is not a list; dropped`);
    }
    let handleDescription;
    if (subType.typeKey === "updateRecord") {
        // A live "" is not a reconstructable value any more than a missing
        // attribute is - skillUpdateRecord's own assertHandleDescriptionNotEmpty
        // throws on an explicit "", so printing one straight into a
        // skillUpdateRecord({...}) call would crash the next time this source
        // loads. Collapse it to undefined here so the printer never sees it.
        handleDescription = optionalString(attrs, "handle_description", where, ctx) || undefined;
    }
    return {
        typeKey: subType.typeKey,
        ...common,
        target,
        ...(fields !== undefined && { fields }),
        ...(filterVariables !== undefined && { filterVariables }),
        ...((subType.typeKey === "searchAspect" || subType.typeKey === "searchTable") && {
            queryDescription: optionalString(attrs, "query_description", where, ctx) ?? "",
        }),
        ...(searchTableKey !== undefined && { searchTableKey }),
        ...(searchTableName !== undefined && { searchTableName }),
        ...(typeof attrs["result_limit"] === "number" && { limit: attrs["result_limit"] }),
        ...(handleDescription !== undefined && { handleDescription }),
    };
}
